        // prepare search parameters
        ;set Filter=pRequest.Filter

        // add or update
        set pResponse = ##class(Ens.StringRequest).%New()
        Set tSC=..Adapter.isSearchExtsExists(pRequest.searchFilter,pRequest.DN,.RetVal)
        set pResponse.StringValue=RetVal
        $$$TRACE(tSC_"RetVal from adapter "_RetVal)
        if $$$ISERR(tSC) {            
            quit
        }



    }
    catch Err {
        set tSC=Err.AsStatus()

        set pResponse.StringValue=$system.Status.GetErrorText(tSC)
    }
    Quit tSC
